import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), rand=(a,b)=>a+Math.random()*(b-a);
const canvas=$('#world'), scene=new THREE.Scene();
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.1;
scene.background=new THREE.Color(0x9ac4bd); scene.fog=new THREE.FogExp2(0x9bbdb3,.0018);
const camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.1,1200);
const hemi=new THREE.HemisphereLight(0xcce7da,0x35452e,1.45);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffedc3,2.4);sun.position.set(-120,190,90);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-250;sun.shadow.camera.right=250;sun.shadow.camera.top=250;sun.shadow.camera.bottom=-250;sun.shadow.bias=-.0002;scene.add(sun);
const fill=new THREE.DirectionalLight(0x76aeb1,.45);fill.position.set(120,50,-150);scene.add(fill);
const mat=(color,roughness=.85,more={})=>new THREE.MeshStandardMaterial({color,roughness,...more});
const mats={bark:mat(0x795b3b),leaf:mat(0x315e3c),leaf2:mat(0x47754a),leaf3:mat(0x244d39),sand:mat(0xd0b77e),stone:mat(0x687565),wood:mat(0x765b3e),roof:mat(0x67463a),wall:mat(0xcbb994),dark:mat(0x263832),jeep:mat(0x8e7045),rubber:mat(0x171b18),metal:mat(0x3c4741,.5),glass:mat(0x598279,.22,{transparent:true,opacity:.6}),cloth:mat(0x263c32),skin:mat(0xb98763),cream:mat(0xe3d7b8),gold:mat(0xd2b86e,.45),flower:mat(0xf0d88d)};
const seaMat=new THREE.ShaderMaterial({uniforms:{uTime:{value:0},uDay:{value:1}},vertexShader:`varying vec2 vUv; varying vec3 vPos; uniform float uTime; void main(){vUv=uv; vec3 p=position; p.z+=sin(p.x*.035+uTime*.55)*.17+cos(p.y*.025+uTime*.35)*.13; vPos=p; gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.);}`,fragmentShader:`varying vec2 vUv; varying vec3 vPos; uniform float uDay; uniform float uTime; void main(){float w=sin(vPos.x*.04+uTime*.5)*cos(vPos.y*.03-uTime*.35); vec3 deep=vec3(.025,.20,.22); vec3 light=vec3(.15,.43,.42); float glint=smoothstep(.72,.98,w+sin(vPos.x*.12+vPos.y*.08)*.2); vec3 c=mix(deep,light,.33+w*.13); c=mix(c,vec3(.75,.79,.63),glint*.2); c*=mix(.48,1.,uDay); gl_FragColor=vec4(c,.97);}` ,transparent:true,depthWrite:true});
const ocean=new THREE.Mesh(new THREE.PlaneGeometry(1400,1400,100,100),seaMat); ocean.rotation.x=-Math.PI/2;ocean.position.y=-1.05;ocean.receiveShadow=true;scene.add(ocean);
const WORLD=250;
function terrainHeight(x,z){const r=Math.sqrt((x/226)**2+(z/215)**2);if(r>=1)return -3;const coast=clamp((1-r)/.18,0,1);const base=2+Math.sin(x*.021)*1.5+Math.cos(z*.017)*1.6+Math.sin((x+z)*.034)*.9;const peaks=[[82,-115,70,37],[-68,-80,52,48],[20,-162,39,35],[135,10,26,38]];let mountain=0;for(const [px,pz,h,s] of peaks){const d=((x-px)**2+(z-pz)**2)/(s*s);mountain+=h*Math.exp(-d*1.12)}return Math.max(-.5,coast*(base+mountain)-.8);}
function onIsland(x,z){return Math.sqrt((x/222)**2+(z/211)**2)<.97;}
function createTerrain(){const n=170,size=500,verts=[],colors=[],indices=[];const cSand=new THREE.Color(0xc7ae78),cGrass=new THREE.Color(0x496a43),cHigh=new THREE.Color(0x657567),cPeak=new THREE.Color(0xa6a99a);for(let iz=0;iz<=n;iz++)for(let ix=0;ix<=n;ix++){const x=-size/2+ix*size/n,z=-size/2+iz*size/n,y=terrainHeight(x,z);verts.push(x,y,z);const r=Math.sqrt((x/226)**2+(z/215)**2);let col;if(r>.88)col=cSand.clone().lerp(cGrass,clamp((.93-r)*14,0,1));else if(y>54)col=cHigh.clone().lerp(cPeak,clamp((y-72)/45,0,.7));else col=cGrass.clone().lerp(cHigh,clamp(y/95,0,.48));const noise=(Math.sin(x*.19+z*.13)*.025);col.offsetHSL(0,0,noise);colors.push(col.r,col.g,col.b);if(ix<n&&iz<n){const a=iz*(n+1)+ix,b=a+n+1;indices.push(a,b,a+1,b,b+1,a+1)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));g.setIndex(indices);g.computeVertexNormals();const m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));m.receiveShadow=true;m.castShadow=false;scene.add(m);}
createTerrain();
// Shoreline foam and beach stones
const rockGeo=new THREE.DodecahedronGeometry(1,0);
for(let i=0;i<240;i++){const a=Math.random()*Math.PI*2,r=rand(205,235),x=Math.cos(a)*r,z=Math.sin(a)*r*.94;if(!onIsland(x,z))continue;const rock=new THREE.Mesh(rockGeo,i%3?mats.stone:mats.sand);rock.position.set(x,terrainHeight(x,z)+rand(.1,.6),z);rock.scale.set(rand(.35,1.4),rand(.2,.8),rand(.35,1.2));rock.rotation.set(rand(0,3),rand(0,3),rand(0,3));rock.castShadow=true;scene.add(rock)}
// Tropical palms and mountain forest, assembled from shared geometry.
const trunkGeo=new THREE.CylinderGeometry(.28,.55,8,7);trunkGeo.translate(0,4,0);
function makeFrondGeo(){const verts=[],idx=[];const steps=8;for(let i=0;i<=steps;i++){const t=i/steps,x=t*5,y=-.2-t*t*2.7,z=Math.sin(t*Math.PI)*.17,w=Math.sin(Math.PI*(t*.9+.05))*.65*(1-.45*t);verts.push(x,y,z-w,x,y,z+w)}for(let i=0;i<steps;i++){const a=i*2;idx.push(a,a+1,a+2,a+1,a+3,a+2)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(idx);g.computeVertexNormals();return g;}
const frondGeo=makeFrondGeo();
function makePalm(x,z,scale=1){const group=new THREE.Group();group.position.set(x,terrainHeight(x,z),z);group.scale.setScalar(scale);const trunk=new THREE.Mesh(trunkGeo,mats.bark);trunk.rotation.z=rand(-.08,.08);trunk.castShadow=true;group.add(trunk);const top=new THREE.Group();top.position.y=7.6;group.add(top);for(let i=0;i<8;i++){const leaf=new THREE.Mesh(frondGeo,[mats.leaf,mats.leaf2,mats.leaf3][i%3]);leaf.rotation.y=i*Math.PI/4+rand(-.1,.1);leaf.rotation.x=rand(-.12,.12);leaf.castShadow=true;top.add(leaf)}const coc=new THREE.Mesh(new THREE.SphereGeometry(.48,8,6),mats.leaf3);coc.position.y=-.12;top.add(coc);scene.add(group);return group;}
function makeBroadTree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);g.scale.setScalar(scale);const tr=new THREE.Mesh(new THREE.CylinderGeometry(.32,.68,7,7),mats.bark);tr.position.y=3.5;tr.castShadow=true;g.add(tr);for(let i=0;i<5;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(rand(3,4.7),1),[mats.leaf,mats.leaf2,mats.leaf3][i%3]);crown.position.set(rand(-2,2),rand(5.3,8.2),rand(-2,2));crown.scale.y=.7;crown.castShadow=true;g.add(crown)}scene.add(g);return g;}
for(let i=0;i<280;i++){let x,z,tries=0;do{x=rand(-208,208);z=rand(-200,200);tries++}while((!onIsland(x,z)||Math.sqrt((x+20)**2+(z-18)**2)<19||Math.sqrt((x-115)**2+(z+145)**2)<17)&&tries<80);if(!onIsland(x,z))continue;const h=terrainHeight(x,z),s=rand(.72,1.35);if(h>42||Math.random()<.19)makeBroadTree(x,z,s);else makePalm(x,z,s)}
// Lush undergrowth and landmark palms
const bushGeo=new THREE.IcosahedronGeometry(1,1);for(let i=0;i<210;i++){const x=rand(-200,200),z=rand(-190,190);if(!onIsland(x,z))continue;const b=new THREE.Mesh(bushGeo,i%2?mats.leaf:mats.leaf2);b.position.set(x,terrainHeight(x,z)+.7,z);b.scale.set(rand(.8,2),rand(.6,1.3),rand(.8,1.7));b.castShadow=true;scene.add(b)}

