const frondGeo=makeFrondGeo();
function makeCanopyGeo(){const pos=[],idx=[],src=frondGeo.attributes.position.array,ind=frondGeo.index.array;for(let k=0;k<8;k++){const a=k*Math.PI/4+rand(-.08,.08),c=Math.cos(a),s=Math.sin(a),off=pos.length/3;for(let i=0;i<src.length;i+=3){const x=src[i],y=src[i+1],z=src[i+2];pos.push(x*c+z*s,y,-x*s+z*c)}for(const q of ind)idx.push(q+off)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setIndex(idx);g.computeVertexNormals();return g;}
const palmCanopy=makeCanopyGeo();
function makePalm(x,z,scale=1){const group=new THREE.Group();group.position.set(x,terrainHeight(x,z),z);group.scale.setScalar(scale);const trunk=new THREE.Mesh(trunkGeo,mats.bark);trunk.rotation.z=rand(-.08,.08);trunk.castShadow=true;group.add(trunk);const crown=new THREE.Mesh(palmCanopy,mats.leaf);crown.position.y=7.6;crown.castShadow=true;group.add(crown);const coc=new THREE.Mesh(new THREE.SphereGeometry(.48,8,6),mats.leaf3);coc.position.y=7.48;group.add(coc);scene.add(group);return group;}

