const hh=Math.floor(hour).toString().padStart(2,'0'),mm=Math.floor((hour%1)*60).toString().padStart(2,'0');clockEl.textContent=`${hh}:${mm}`;$('#survival-day').textContent=`DAY ${String(Math.floor(elapsed/240)+1).padStart(2,'0')}`;
